use core::sync::atomic::{AtomicU32 as A,Ordering as O};fn one(o:O){let a=A::new(3);check(a.fetch_sub(5,o)==3);check(a.load(O::Relaxed)==4294967294);check(a.fetch_sub(4294967295,o)==4294967294);check(a.load(O::Relaxed)==4294967295);check(a.fetch_sub(0,o)==4294967295);check(a.load(O::Relaxed)==4294967295);}fn main(){one(O::Relaxed);one(O::Release);one(O::Acquire);one(O::AcqRel);one(O::SeqCst);}
